package dev.unifieddesktop.app

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * T15-6 item 1: the runtime chooser against tiny hand-built ELF fixtures
 * (app/src/test/resources/elf/, generated by the t15-6 fixture script - a few
 * dozen bytes each, no downloads). Same shape as the ChangePropertyWire tests:
 * pure input bytes in, pure decision out.
 */
class LinuxRuntimeTest {

    private fun fixture(name: String): ByteArray =
        javaClass.getResourceAsStream("/elf/$name")!!.use { it.readBytes() }

    @Test
    fun arm64DynamicChoosesNativeArm64WithTheInterp() {
        val d = LinuxRuntime.choose(fixture("arm64-dyn.bin"))
        assertEquals(LinuxRuntime.Mode.NATIVE_ARM64, d.mode)
        assertTrue(d.dynamic)
        assertEquals("/lib/ld-linux-aarch64.so.1", d.interp)
        assertNull(d.reason)
    }

    @Test
    fun arm64StaticChoosesNativeArm64WithoutAnInterp() {
        val d = LinuxRuntime.choose(fixture("arm64-static.bin"))
        assertEquals(LinuxRuntime.Mode.NATIVE_ARM64, d.mode)
        assertTrue(!d.dynamic)
        assertNull(d.interp)
        assertNull(d.reason)
    }

    @Test
    fun x86_64DynamicChoosesBox64WithTheInterp() {
        val d = LinuxRuntime.choose(fixture("x86-dyn.bin"))
        assertEquals(LinuxRuntime.Mode.BOX64_X86_64, d.mode)
        assertTrue(d.dynamic)
        assertEquals("/lib64/ld-linux-x86-64.so.2", d.interp)
        assertNull(d.reason)
    }

    @Test
    fun x86_64StaticChoosesBox64WithoutAnInterp() {
        val d = LinuxRuntime.choose(fixture("x86-static.bin"))
        assertEquals(LinuxRuntime.Mode.BOX64_X86_64, d.mode)
        assertTrue(!d.dynamic)
        assertNull(d.interp)
    }

    @Test
    fun a32BitElfIsUnsupported() {
        val d = LinuxRuntime.choose(fixture("i386-32bit.bin"))
        assertEquals(LinuxRuntime.Mode.UNSUPPORTED, d.mode)
        assertNotNull(d.reason)
        assertTrue(d.reason!!.contains("32-bit"))
    }

    @Test
    fun bigEndianIsUnsupported() {
        val d = LinuxRuntime.choose(fixture("arm64-be.bin"))
        assertEquals(LinuxRuntime.Mode.UNSUPPORTED, d.mode)
        assertTrue(d.reason!!.contains("big-endian"))
    }

    @Test
    fun garbageIsUnsupportedWithAReason() {
        val d = LinuxRuntime.choose(fixture("not-elf.bin"))
        assertEquals(LinuxRuntime.Mode.UNSUPPORTED, d.mode)
        assertTrue(d.reason!!.contains("magic"))
    }

    @Test
    fun aShortFileIsUnsupported() {
        val d = LinuxRuntime.choose(fixture("truncated.bin"))
        assertEquals(LinuxRuntime.Mode.UNSUPPORTED, d.mode)
        assertTrue(d.reason!!.contains("shorter than an ELF header"))
    }

    @Test
    fun anEmptyByteArrayIsUnsupported() {
        val d = LinuxRuntime.choose(ByteArray(0))
        assertEquals(LinuxRuntime.Mode.UNSUPPORTED, d.mode)
        assertNotNull(d.reason)
    }

    /** A header-only probe cannot prove static vs dynamic -> never guessed. */
    @Test
    fun truncatedProgramHeadersAreUnsupported() {
        val d = LinuxRuntime.choose(fixture("truncated-phdrs.bin"))
        assertEquals(LinuxRuntime.Mode.UNSUPPORTED, d.mode)
        assertTrue(d.reason!!.contains("truncated program headers"))
    }

    /** The real demo target (Firefox ARM64 Linux, fetched at runtime) must land in
     *  NATIVE_ARM64. Hand-built header replica of firefox-160.0 (ET_DYN, EM_AARCH64,
     *  PT_INTERP at the standard offsets) - the real 180 MB binary is never committed. */
    @Test
    fun firefoxShapeArm64DynBinaryChoosesNative() {
        val d = LinuxRuntime.choose(fixture("arm64-dyn.bin"))
        assertEquals(LinuxRuntime.Mode.NATIVE_ARM64, d.mode)
        assertEquals("/lib/ld-linux-aarch64.so.1", d.interp)
    }

    @Test
    fun decisionIsSafeForEveryBranch() {
        // mode/dynamic/interp/reason are the only fields LinuxLaunch reads; make sure
        // reason is null exactly when the mode is supported.
        for (f in listOf("arm64-dyn.bin", "arm64-static.bin", "x86-dyn.bin", "x86-static.bin")) {
            assertNull(f, LinuxRuntime.choose(fixture(f)).reason)
        }
        for (f in listOf("i386-32bit.bin", "arm64-be.bin", "not-elf.bin",
                         "truncated.bin", "truncated-phdrs.bin")) {
            assertNotNull(f, LinuxRuntime.choose(fixture(f)).reason)
        }
    }
}
